-- THE HOLSTERS THEMSELVES: the shells of "Valentino Holsters" (Nexus mod 18100) round the weapons on the body, when
-- that mod is installed (its archive; the port ships none of its files). data/shells.lua is generated by
-- tools/holsters/make_holster_shell.py from the mod's meshes.
--
-- Each shell is a plain mesh of the mod (one of its garments, the chunks of one part) carried rigidly by a bone slot,
-- like the weapon copies:
--   - THE LEG HOLSTER at the drawing hip, one shell per kind of handgun (pistol, revolver, Overture, Malorian). It goes
--     with the port's own place for a pistol (at the belt): its local transform is the place's pose times the inverse
--     of the pose the mod gave its own weapon in that shell, so the port's weapon sits in it as the mod's did;
--   - THE SHOULDER HARNESS on Spine3 (the Chest slot), with the holster under the off arm when a pistol hangs there and
--     the knife sheath on its strap when a knife is on the chest. These are made to fit the body, so they hang where
--     the mod put them (the inverse of the bone's bind pose) and the weapon's place moves into them: the place's pose
--     IS the pose the mod gave its weapon there. The holster under the arm alone stands off that spot by UNDERARM_SHIFT.
-- A shell stays on the body while its weapon is in the hand: the holster is empty then, not gone.
local D = require("data/shells")

local M = {}

local function qmul(a, b)
  return { a[4] * b[1] + a[1] * b[4] + a[2] * b[3] - a[3] * b[2],
           a[4] * b[2] - a[1] * b[3] + a[2] * b[4] + a[3] * b[1],
           a[4] * b[3] + a[1] * b[2] - a[2] * b[1] + a[3] * b[4],
           a[4] * b[4] - a[1] * b[1] - a[2] * b[2] - a[3] * b[3] }
end
local function qconj(a) return { -a[1], -a[2], -a[3], a[4] } end
local function qrot(q, v)
  local r = qmul(qmul(q, { v[1], v[2], v[3], 0 }), qconj(q))
  return { r[1], r[2], r[3] }
end

-- a * b for poses { p, q }, and the inverse of one
local function compose(a, b)
  local r = qrot(a.q, b.p)
  return { p = { a.p[1] + r[1], a.p[2] + r[2], a.p[3] + r[3] }, q = qmul(a.q, b.q) }
end
local function inverse(a)
  local iq = qconj(a.q)
  local r = qrot(iq, a.p)
  return { p = { -r[1], -r[2], -r[3] }, q = iq }
end

---------------------------------------------------------------- is the mod there, and which body

local present = nil
function M.available()
  if present ~= nil then return present end
  local ok, yes = pcall(function()
    local depot = Game.GetResourceDepot and Game.GetResourceDepot() or GetResourceDepot()
    return depot:ArchiveExists(D.archive)
  end)
  present = ok and yes == true
  print("[Holster] Valentino Holsters " .. (present and "found: holster shells on" or "not installed: no shells"))
  return present
end

-- 'm' or 'w': the base body the player has (the mod's meshes are made per body).
function M.body()
  local ok, female = pcall(function()
    return NameToString(Game.GetPlayer():GetResolvedGenderName()) == "Female"
  end)
  return (ok and female) and "w" or "m"
end

---------------------------------------------------------------- the places the shells hold

local SIDE_OF = { hip_r = "r", hip_l = "l", underarm_l = "l", underarm_r = "r", chest_l = "l", chest_r = "r" }
local DESIGN = { underarm_l = "underarm", underarm_r = "underarm", chest_l = "cknife", chest_r = "cknife" }

-- The holster under the arm and its weapon, moved from where the mod put them: 3 cm further to the side and 1 cm back
-- round the chest (model space: +x right, +y forward; asked 2026-11-05: on the chest it was in the way).
local UNDERARM_SHIFT = { l = { -0.03, -0.01, 0 }, r = { 0.03, -0.01, 0 } }

-- `pose` (model space) of a harness part, moved the part's own shift.
local function shifted(part, side, pose)
  if part ~= "underarm" then return pose end
  local d = UNDERARM_SHIFT[side]
  return { p = { pose.p[1] + d[1], pose.p[2] + d[2], pose.p[3] + d[3] }, q = pose.q }
end

local placeCache = {}
-- The place a weapon takes when the shells are on: a harness place moves into its holster (the mod's weapon pose in
-- the Chest bone's frame); every other place is the port's own.
function M.place(place, body)
  local part = DESIGN[place.name]
  if part == nil then return place end
  local ck = place.name .. "|" .. body .. (place.melee and "|m" or "|g")
  local c = placeCache[ck]
  if c then return c end
  local side = SIDE_OF[place.name]
  local pose = compose(inverse(D.bind[body].chest), shifted(part, side, D[part][side][body].fit))
  c = {}
  for k, v in pairs(place) do c[k] = v end
  c.pos, c.rot = pose.p, pose.q
  if place.pull then
    local axis = qrot(pose.q, place.melee and { 0, 0, -1 } or { 0, -1, 0 })     -- out along the handle / grip first
    c.pullAxis = axis
  end
  placeCache[ck] = c
  return c
end

-- Which leg shell a handgun takes: by its appearance resource (the factory key its copy's look starts with) and type.
local function legKind(look, typeName)
  look = look or ""
  if look:find("Overture", 1, true) then return "overture" end
  if look:find("Silverhand", 1, true) or look:find("Malorian", 1, true) then return "malorian" end
  if typeName == "Wea_Revolver" then return "revolver" end
  return "pistol"
end

-- The shells the weapons on the body need: name -> { ent, comp, slot, pose { p, q } in the slot's frame }.
-- `copies` are the holster's copies ({ place, look, typeName }).
function M.wanted(copies, body)
  local out = {}
  local harness = false
  for _, c in pairs(copies) do
    local name = c.place.name
    local side = SIDE_OF[name]
    if name == "hip_r" or name == "hip_l" then
      if c.kind == "pistol" then
        local kind = legKind(c.look, c.typeName)
        local spec = D.leg[side][kind][body]
        out["leg_" .. side] = { ent = spec.ent, comp = c.place.comp, slot = c.place.slot,
          pose = compose({ p = c.place.pos, q = c.place.rot }, inverse(spec.fit)) }
      end
    elseif DESIGN[name] ~= nil then
      local part = DESIGN[name]
      out[part .. "_" .. side] = { ent = D[part][side][body].ent, comp = "ItemAttachmentSlots", slot = "Chest",
        pose = compose(inverse(D.bind[body].chest), shifted(part, side, { p = { 0, 0, 0 }, q = { 0, 0, 0, 1 } })) }
      harness = true
    end
  end
  if harness then
    out.harness = { ent = D.harness[body], comp = "ItemAttachmentSlots", slot = "Chest",
      pose = inverse(D.bind[body].chest) }
  end
  return out
end

return M
